package cn.zj.zjmarket.verification;
import cn.zj.zjmarket.domain.refund.model.Refund.Settings;
import cn.zj.zjmarket.domain.refund.service.RefundService;
import cn.zj.zjmarket.domain.payment.adapter.repository.ISettlementRepository;
import cn.zj.zjmarket.infrastructure.adapter.repository.*;
import cn.zj.zjmarket.infrastructure.adapter.port.refund.SimulatedRefundChannel;
import cn.zj.zjmarket.infrastructure.adapter.port.payment.RocketMqSettlementTransport;
import org.springframework.context.ConfigurableApplicationContext;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import com.fasterxml.jackson.databind.ObjectMapper;
import javax.sql.DataSource;
import java.nio.file.*;
import java.util.*;
import static cn.zj.zjmarket.verification.SyncCommands.*;
/** Own fresh actual-A roster only. Never updates A's database, clocks or historical funds. */
final class ActualRefundSyncCommands {
 static void run(ConfigurableApplicationContext ctx,Path work,String mode)throws Exception{check(work.getFileName().toString().matches("b05[45]-[A-Za-z0-9-]+"),"fresh B054/B055 batch");if(mode.startsWith("refund-release-")){release(ctx,work,mode);return;}var json=new ObjectMapper();var manifest=json.readTree(Files.readAllBytes(work.resolve("reconciliation-restart.json")));var db=new JdbcTemplate(ctx.getBean(DataSource.class));String oid=manifest.path("paidOrder").asText();var f=db.queryForMap("SELECT * FROM b_refund WHERE order_id=?",oid);String id=f.get("refund_id").toString(),one=RefundOutbox.eventId(id,1),two=RefundOutbox.eventId(id,2);
  if(mode.equals("refund-offline")){check(f.get("funds_status").equals("NONE")&&f.get("eligibility_status").equals("ELIGIBLE"),"fresh eligible actual A refund");var ds=ctx.getBean(DataSource.class);var tx=new TransactionTemplate(new DataSourceTransactionManager(ds));tx.setIsolationLevel(org.springframework.transaction.TransactionDefinition.ISOLATION_READ_COMMITTED);var settings=Settings.defaults();var repo=new RefundRepository(ds,tx,settings,"s01","c01");repo.enableOutbox(new RefundOutbox(db,"zj-market","s01","c01"));repo.admit(id);try(var service=new RefundService(repo,new SimulatedRefundChannel(ds,tx,settings),settings)){service.recover(id);service.recover(id);}check(db.queryForObject("SELECT funds_status FROM b_refund WHERE refund_id=?",String.class,id).equals("SUCCEEDED")&&db.queryForObject("SELECT COUNT(*) FROM b_trade_outbox WHERE refund_id=? AND state='READY'",Long.class,id)==2,"A stopped: funds commit and both outboxes persist without RPC/MQ");Files.writeString(work.resolve("refund-original.json"),json.writeValueAsString(Map.of("refundId",id,"paidHash",db.queryForObject("SELECT success_hash FROM b_payment WHERE payment_id=?",String.class,f.get("payment_id")),"firstHash",db.queryForObject("SELECT body_hash FROM b_trade_outbox WHERE event_id=?",String.class,one),"secondHash",db.queryForObject("SELECT body_hash FROM b_trade_outbox WHERE event_id=?",String.class,two))));}
  else{var store=ctx.getBean(ISettlementRepository.class);var transport=ctx.getBean(RocketMqSettlementTransport.class);transport.start();if(mode.equals("refund-sync-live")){
    var success=store.claim(two);check(success!=null,"own success delivery");transport.publish(success);store.delivered(success,true,null);
    waitFor(()->db.queryForObject("SELECT COUNT(*) FROM b_trade_inbox WHERE original_event_id=? AND event_id NOT LIKE 'rpc-%'",Long.class,two)>0,45000,"actual A signed MQ refund result");store.applyInbox(10000);check(db.queryForObject("SELECT accepted_version FROM b_refund WHERE refund_id=?",Long.class,id)==2,"actual signed MQ success accepted");
    var pending=store.claim(one);check(pending!=null,"old pending original event");transport.publish(pending);store.delivered(pending,true,null);
    waitFor(()->db.queryForObject("SELECT COUNT(*) FROM b_trade_inbox WHERE original_event_id=? AND event_id NOT LIKE 'rpc-%'",Long.class,one)>0,45000,"actual A old event returns higher current version");store.applyInbox(10000);check(db.queryForObject("SELECT COUNT(*) FROM b_trade_inbox WHERE original_event_id=? AND state='WAITING_DEPENDENCY'",Long.class,one)>0,"higher MQ result waits full typed query");
    var result=transport.query(pending);check(result!=null&&result.authority()!=null,"actual authenticated Event.query plus Trade.query authority");store.receive(result);store.applyInbox(10000);check(db.queryForObject("SELECT state FROM b_trade_outbox WHERE event_id=?",String.class,one).equals("DONE"),"higher known version original event completes");
    var compensation=transport.queryTrade(pending);check(compensation!=null&&compensation.authority()!=null,"typed Trade query loss compensation");store.receive(compensation);store.applyInbox(10000);transport.publish(success);transport.publish(pending);
   }else{check(mode.equals("refund-sync-recover"),"owned recovery mode");var row=db.queryForMap("SELECT * FROM b_trade_outbox WHERE event_id=?",one);var delivery=new cn.zj.zjmarket.domain.payment.model.valobj.TradeDelivery(one,f.get("payment_id").toString(),oid,f.get("user_id").toString(),new String((byte[])row.get("body"),java.nio.charset.StandardCharsets.UTF_8),row.get("body_hash").toString(),"DONE",0,"read-only-query");var receipt=transport.query(delivery);check(receipt!=null&&receipt.authority()!=null,"new B JVM replays original event result with current authority");store.receive(receipt);store.applyInbox(10000);}
    check(db.queryForObject("SELECT COUNT(*) FROM b_refund WHERE refund_id=? AND funds_status='SUCCEEDED' AND sync_status='ACCEPTED' AND accepted_version=2 AND accepted_status='SUCCEEDED'",Long.class,id)==1,"funds and accepted high water retained");
  }
  var original=json.readTree(Files.readAllBytes(work.resolve("refund-original.json")));check(original.path("paidHash").asText().equals(db.queryForObject("SELECT success_hash FROM b_payment WHERE payment_id=?",String.class,f.get("payment_id")))&&original.path("firstHash").asText().equals(db.queryForObject("SELECT body_hash FROM b_trade_outbox WHERE event_id=?",String.class,one))&&original.path("secondHash").asText().equals(db.queryForObject("SELECT body_hash FROM b_trade_outbox WHERE event_id=?",String.class,two)),"original funds and event bytes never rewritten");boolean released=Files.exists(work.resolve("refund-release-original.json"));check(db.queryForObject("SELECT state FROM b_inventory_reservation WHERE order_id=?",String.class,oid).equals(released?"RELEASED":"HELD")&&db.queryForObject("SELECT COUNT(*) FROM b_purchase_guard WHERE active_order_id=?",Long.class,oid)==(released?0:1)&&db.queryForObject("SELECT COUNT(*) FROM b_sim_refund_attempt WHERE refund_id=?",Long.class,id)==1,"one actual channel refund and expected inventory ownership");if(released)check(db.queryForObject("SELECT COUNT(*) FROM b_inventory_ledger WHERE order_id=? AND kind='RELEASE'",Long.class,oid)==1,"sync after release does not release twice");var owned=new ArrayList<String>();manifest.path("members").forEach(x->owned.add(x.asText()));B05Conservation.capture(db,owned,work,mode);Files.writeString(work.resolve(mode+".txt"),"status=PASSED\nactual-A-fresh-FAILED/original-payment/full-refund/immutable-Outbox=PASSED\nmode="+mode+"\nrefundId="+id+"\n");
 }
 private static void release(ConfigurableApplicationContext ctx,Path work,String mode)throws Exception{check(work.getFileName().toString().startsWith("b055-"),"B055 fresh actual A release only");var json=new ObjectMapper();var manifest=json.readTree(Files.readAllBytes(work.resolve("reconciliation-restart.json")));String oid=manifest.path("paidOrder").asText();var ds=ctx.getBean(DataSource.class);var db=new JdbcTemplate(ds);var f=db.queryForMap("SELECT * FROM b_refund WHERE order_id=?",oid);String id=f.get("refund_id").toString();check(f.get("funds_status").equals("SUCCEEDED")&&f.get("eligibility_status").equals("ELIGIBLE")&&f.get("sync_status").equals("PENDING")&&((Number)f.get("accepted_version")).longValue()==0,"funds refunded while actual A is stopped, no A ACK yet");var tx=new TransactionTemplate(new DataSourceTransactionManager(ds));tx.setIsolationLevel(org.springframework.transaction.TransactionDefinition.ISOLATION_READ_COMMITTED);var repo=new RefundRepository(ds,tx,Settings.defaults(),"s01","c01");repo.enableOutbox(new RefundOutbox(db,"zj-market","s01","c01"));var release=new RefundReleaseRepository(ds,repo);release.validateSchema();var stock=db.queryForMap("SELECT i.* FROM b_inventory_account i JOIN b_market_order o ON o.goods_id=i.goods_id WHERE o.order_id=?",oid);String paid=db.queryForObject("SELECT success_hash FROM b_payment WHERE payment_id=?",String.class,f.get("payment_id"));
 if(mode.equals("refund-release-offline")){check(release.recover(id)&&release.replay(id),"actual full-refund terminal proof releases without A");var after=db.queryForMap("SELECT i.* FROM b_inventory_account i JOIN b_market_order o ON o.goods_id=i.goods_id WHERE o.order_id=?",oid);check(((Number)after.get("available")).longValue()==((Number)stock.get("available")).longValue()+1&&((Number)after.get("reserved")).longValue()==((Number)stock.get("reserved")).longValue()-1&&after.get("sold").equals(stock.get("sold")),"actual refund moves HELD to available without sold change");Files.writeString(work.resolve("refund-release-original.json"),json.writeValueAsString(Map.of("refundId",id,"orderId",oid,"paidHash",paid,"proofHash",db.queryForObject("SELECT proof_hash FROM b_refund_release WHERE refund_id=?",String.class,id))));}
 else{check(mode.equals("refund-release-recover")&&release.replay(id),"new B JVM validates the original release proof");check(stock.equals(db.queryForMap("SELECT i.* FROM b_inventory_account i JOIN b_market_order o ON o.goods_id=i.goods_id WHERE o.order_id=?",oid)),"new JVM replay changes no stock");}
 var original=json.readTree(Files.readString(work.resolve("refund-release-original.json")));check(original.path("paidHash").asText().equals(paid)&&original.path("proofHash").asText().equals(db.queryForObject("SELECT proof_hash FROM b_refund_release WHERE refund_id=?",String.class,id))&&db.queryForObject("SELECT COUNT(*) FROM b_inventory_ledger WHERE order_id=? AND kind='RELEASE'",Long.class,oid)==1&&db.queryForObject("SELECT COUNT(*) FROM b_market_order WHERE order_id=? AND business_status='CLOSED' AND close_basis='FULL_REFUND_CONFIRMED'",Long.class,oid)==1&&db.queryForObject("SELECT COUNT(*) FROM b_purchase_guard WHERE active_order_id=?",Long.class,oid)==0,"original paid fact, immutable proof, one release, closed order and own guard cleared");Files.writeString(work.resolve(mode+".txt"),"status=PASSED\nactual-A-stopped/full-refund-nonfulfillment-proof/no-A-ACK-required=PASSED\nunique-RELEASE/closed/own-guard/no-sold-change/original-payment=PASSED\nnew-B-JVM-replay-no-second-release=PASSED\n");
 }
}
